import { loadRecord_quantum_order_pipeline } from "../src/service.mjs";

const cases = [
  {
    input: {"region":{"quota":8}},
    code: "SCHEMA_ZONE_MISSING",
    path: "region.zone",
  },
  {
    input: {"region":{"zone":"north","quota":4}},
    code: "SCHEMA_QUOTA_RANGE",
    path: "region.quota",
  },
];

const errors = cases.map(({ input }) => {
  try {
    loadRecord_quantum_order_pipeline(input);
    return null;
  } catch (error) {
    return error;
  }
});

const structured = errors.every((error, index) =>
  error?.code === cases[index].code && error?.path === cases[index].path
);
const presentationOnly = errors.every((error, index) =>
  error?.message.includes(cases[index].path) &&
  error?.cause?.code === cases[index].code
);
const valid = loadRecord_quantum_order_pipeline({"region":{"zone":"north","quota":8}});

if (structured && valid["region"]["quota"] === 8) {
  console.log("FIXED: structured schema errors preserve code and field path");
  process.exit(0);
}
if (presentationOnly) {
  console.log("CHECK_FAILED: record loading does not preserve the required error contract");
  process.exit(2);
}

console.log("UNFIXED: schema failures lose their structured code or field path");
process.exit(1);

function validateRecord(record) {
  if (typeof record.region?.zone !== "string") {
    throw Object.assign(new Error("zone is required"), {
      code: "SCHEMA_ZONE_MISSING",
      path: "region.zone",
    });
  }
  if (!Number.isInteger(record.region?.quota) || record.region.quota < 5) {
    throw Object.assign(new Error("quota is below its minimum"), {
      code: "SCHEMA_QUOTA_RANGE",
      path: "region.quota",
    });
  }
  return record;
}

export function loadRecord_quantum_order_pipeline(record) {
  return validateRecord(record);
}

/**
 * Helper routines for quantum-order-pipeline
 *
 * Provides header builders, service context factories, and validation guards.
 */
import { formatDomainName_quantum_order_pipeline, generateTraceId_quantum_order_pipeline } from "../utils.js";

export function getDomainHeader_quantum_order_pipeline(domain: string): string {
  return "X-Domain-" + formatDomainName_quantum_order_pipeline(domain);
}

export function createServiceContext_quantum_order_pipeline(domain: string): { domain: string; traceId: string; timestamp: number } {
  return {
    domain: formatDomainName_quantum_order_pipeline(domain),
    traceId: generateTraceId_quantum_order_pipeline(),
    timestamp: Date.now(),
  };
}

export function validateDomainHeader_quantum_order_pipeline(header: string): boolean {
  return typeof header === "string" && header.startsWith("X-Domain-");
}

export function buildResponseEnvelope_quantum_order_pipeline<T>(
  data: T,
  status = "ok",
): { status: string; data: T; timestamp: string } {
  return { status, data, timestamp: new Date().toISOString() };
}
